             (Z_to_bv 64 l1) (Z_to_bv 64 L) (Z_to_bv 64 l3) (Z_to_bv 64 l2) a5 a6 a7 (Z_to_bv 64 (SS + 6 + l1))
             (Z_to_bv 64 (DST + seg)) (Z_to_bv 64 (DST + dcap)) x21 x22 x23 (Z_to_bv 64 DST) (Z_to_bv 64 DT) x26
             (Z_to_bv 64 2147450880) (Z_to_bv 64 (DST + 3 * seg)) (Z_to_bv 64 (DST + 2 * seg)) (Z_to_bv 64 (SS + 6))
             (Z_to_bv 64 SS))
        FR (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

