  Hypothesis BIG1 : forall mm l1 l2 l3 L (x9 a5 a6 a7 x21 x22 x23 x26 t2 : word),
    Z4S mm -> 8 <= l1 < 65536 -> 0 <= l2 < 65536 -> 0 <= l3 < 65536 -> L = l1 + l2 + l3 + 6 -> L <= n -> 6 <= dcap ->
